/*
 * 증권의 이름가져오기
 */
/**
 * @method
 * @name fn_getSecuGrpNm
 * @description desc
 * @param {string} sid desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getSecuGrpNm = function(sid) {
    var snm = "";
    if (sid == "ST") {
        snm = "주권";
    } else if (sid == "MF") {
        snm = "투자";
    } else if (sid == "RT") {
        snm = "부동산투자";
    } else if (sid == "SC") {
        snm = "선박투자";
    } else if (sid == "IF") {
        snm = "사회간접자본투융자회사";
    } else if (sid == "DR") {
        snm = "주식예탁증서";
    } else if (sid == "SW") {
        snm = "신주인수권증권";
    } else if (sid == "SR") {
        snm = "신주인수권증서";
    } else if (sid == "EW") {
        snm = "ELW";
    } else if (sid == "EF") {
        snm = "ETF";
    } else if (sid == "BC") {
        snm = "수익증권";
    } else if (sid == "FE") {
        snm = "외국ETF";
    } else if (sid == "FS") {
        snm = "외국주권";
    }
    /* ETN 추가항목  [start] */
    else if (sid == "EN") {
        snm = "ETN";
    }
    /* ETN 추가항목  [end] */
    return snm;
};


/*
 * 화면번호를 이용하여 증권그룹ID를 조회한다. 화면open 즉시 수행되어야 한다.
 *
 * 2010.05.30 기업인수목적 회사 메뉴 추가로 인해  GFORM에서 화면 ID 사용
 * 화면 ID 또는 그룹코드 변경시 주의 
 */
/**
 * @method
 * @name fn_getSecuGrpId
 * @description desc
 * @param {string} par desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getSecuGrpId = function(par) {
    /* ETN 추가항목(변경)  [start] */
    var arrMgp = [{
        mid: "STF08011",
        sid: ["EN"]
    }, {
        mid: "STF08041",
        sid: ["EN"]
    }, {
        mid: "STF08042",
        sid: ["EN"]
    }, {
        mid: "STF08043",
        sid: ["EN"]
    }, {
        mid: "STF08044",
        sid: ["EN"]
    }, {
        mid: "STF08300",
        sid: ["EN"]
    }, {
        mid: "STF05340",
        sid: ["EF"]
    }];
    for (var i = 0; i < arrMgp.length; i++) {
        if (par == arrMgp[i].mid) {
            return (arrMgp[i].sid);
        }
    }
    alert(scwin.MSG_NO_FIND_SGRP);
};


/*
 * 유가예비심사기업찾기
 */
/**
 * @method
 * @name fn_PopFindExamCorp
 * @description desc
 * @param {string} pSecjGrpId desc
 * @returns
 * @hidden N
 * @exception
 * @example
