 */
/**
 * @method
 * @name fn_clearPanel
 * @description desc
 * @param {string} o desc
 * @param {string} ec desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_clearPanel = function(o, ec) {
    var e;
    if (o != undefined) {
        for (var i = 0; i < o.children.length; i++) {
            e = o.children.item(i);
            if (scwin.isInArr(e, ec)) {
                continue;
            }
            if (e.tagName.toUpperCase() == "OBJECT") {
                switch (e.classid) {
                    case "clsid:D7779973-9954-464e-9708-DA774CA50E13": // maskedit
                        e.setValue("");
                        break;
                    case "clsid:BB4533A0-85E0-4657-9BF2-E8E7B100D47E": // combo
                        e.setSelectedIndex(-1);
                        break;
                    case "clsid:F73C0958-D8FE-43a5-9BB0-0F651C5A2BCC": // radio
                        e.setValue("");
                        break;
                    case "clsid:1455BE02-C41B-4115-B21C-32380507DC8F": // textarea
                        e.setValue("");
                        break;
                    case "clsid:71E7ACA0-EF63-4055-9894-229B056E9C31": // grid
                        break;
                }
            } else if (e.tagName.toUpperCase() == "INPUT") {
                switch (e.type.toUpperCase()) {
                    case "TEXT":
                        e.setValue("");
                        break;
                    case "CHECKBOX":
                        e.setValue(0);
                        break;
                }
            } else if (e.tagName.toUpperCase() == "SELECT") {
                switch (e.type.toUpperCase()) {
                    case "SELECT-ONE":
                        e.setDisabled(false); //"disabled";
                        break;
                }
            }
        }
    }
};






/*
 * dataset의 내용을 반환한다. (로그 사용)
 */
/**
 * @method
 * @name fn_logDSet
 * @description desc
 * @param {string} o desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_logDSet = function(o) {
    var log = "",
        i, j;
    if (o != undefined) {
        log = "<<" + o.id + ">>";
        for (i = 1; i <= o.getTotalRow(); i++) {
            log = log + "\n" + "<<row:" + i + ">>";
            for (j = 1; j <= o.getTotalCol(); j++) {
                log = log + "\n" + o.ColumnID(j) + ":" + o.getCellData(i, j);
            }
        }
    }
    return log;
};





