/*
 * 일자 + 시간 데이타를 일자,시간으로 나누는 함수
 * nullable : Y 이면 데이타가 없으수도 있음.
 */
/**
 * @method
 * @name divideDtsDataForDdTm
 * @description desc
 * @param {string} dts desc
 * @param {string} rowIndex desc
 * @param {string} isNullable desc
 * @param {string} colNameDdTm desc
 * @param {string} colNameDd desc
 * @param {string} colNameTm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.divideDtsDataForDdTm = function(dts, rowIndex, isNullable, colNameDdTm, colNameDd, colNameTm) {
    var tmpDdTm = "";
    tmpDdTm = dts.getCellData(rowIndex, colNameDdTm);
    if (isNullable == "Y" && tmpDdTm.length < 7) return;
    if (
        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************
        tmpDdTm.length > 7, tmpDdTm.substring(0, 8)) dts.setCellData(rowIndex, colNameDd);
    if (
        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************
        tmpDdTm.length > 8, tmpDdTm.substring(8)) dts.setCellData(rowIndex, colNameTm);
};


/*
 * 일자,시간 체크 함수
 * isCheckCurDate : 오늘 날짜를 포함해서 비교를 할지 여부 ( 유가 : 미포함, 코스닥 : 포함 )
 */
/**
 * @method
 * @name checkDdTm
 * @description desc
 * @param {string} gubun desc
 * @param {string} obj desc
 * @param {string} msg desc
 * @param {string} includeCurDate desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.checkDdTm = function(gubun, obj, msg, includeCurDate) {
    if (gubun == "DD") {
        if (obj.text.length != 8) {
            alert("[" + msg + "일]을 정확히 입력하세요.");
            obj.focus();
            return false;
        }
        var vCurDate = $c.ut.cGetToday("yyyymmdd");
        if (includeCurDate) {
            if (vCurDate > $c.stf.getObjectValue(obj)) {
                alert("[" + msg + "일]을 현재일 이후로 입력하세요.");
                obj.focus();
                return false;
            }
        } else {
            if (vCurDate >= $c.stf.getObjectValue(obj)) {
                alert("[" + msg + "일]을 익일 이후로 입력하세요.");
                obj.focus();
                return false;
            }
        }
    } else if (gubun == "TM") {
        if (obj.text.length == 0) return true;
        if (obj.text.length != 6) {
            alert("[" + msg + "시간]을 [시,분,초]까지 정확히 입력하세요.");
            obj.focus();
            return false;
        }
        var tmp = obj.getText();
        if (eval(tmp.substring(0, 2)) > 23) {
            alert("[" + msg + "시간중 시]를 정확히 입력하세요.");
            obj.focus();
            return false;
        }
        if (eval(tmp.substring(2, 4)) > 59) {
            alert("[" + msg + "시간중 분]을 정확히 입력하세요.");
            obj.focus();
            return false;
        }
        if (eval(tmp.substring(4)) > 59) {
            alert("[" + msg + "시간중 초]를 정확히 입력하세요.");
            obj.focus();
            return false;
        }
    } else if (gubun == "TM2") {
        if (obj.text.length == 0) return true;
        if (obj.text.length != 4) {
            alert("[" + msg + "시간]을 [시,분]까지 정확히 입력하세요.");
            obj.focus();
            return false;
        }
        var tmp = obj.getText();
        if (eval(tmp.substring(0, 2)) > 23) {
            alert("[" + msg + "시간중 시]를 정확히 입력하세요.");
            obj.focus();
            return false;
        }
        if (eval(tmp.substring(2, 4)) > 59) {
            alert("[" + msg + "시간중 분]을 정확히 입력하세요.");
            obj.focus();
            return false;
        }
    }
    return true;
};


/*
 * 전화번호 숫자 체크 함수
 */
/**
 * @method
 * @name fn_checkPhoneNumber
 * @description desc
 * @param {string} phoneNum desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_checkPhoneNumber = function(phoneNum) {
    var pHome = "/^0\\d{8,9}$/g";
    var pGeneral = "/^0\\d{8,10}$/g";
    phoneNum = phoneNum.replace(/[-\s]+/g, "");
    return (eval(pHome).test(phoneNum) || eval(pGeneral).test(phoneNum));
};


/*
 * 그리드에서 수정할때와  신규등록시 변경전 데이타의 ROWCONT 구하기
 */
/**
 * @method
 * @name fn_getRowIdx
 * @description desc
 * @param {string} vKey desc
 * @param {string} dtsObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getRowIdx = function(vKey, dtsObj) {
    var vRow;
    if (vKey == "") {
        vRow = dtsObj.getTotalRow();
    } //신규등록시 
    else if (vKey != "") {
        vRow = dtsObj.getFocusedRowIndex() - 1;
    } //수정시 

    return vRow;
};




/*
 * 관리종목지정(유) 관련해서
 * 현재 업무를 저장할수 있는지 여부를 판단해줌
 */
/**
 * @method
 * @name fn_getMstStatus
 * @description desc
 * @param {string} param_Dts desc
 * @param {string} tpCd desc
 * @param {string} obj desc
 * @param {string} flag desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getMstStatus = function(param_Dts, tpCd, obj, flag) {
    var isFlag = false;
    var url = "";

    // 현재 작업이 종목별일 경우
    if (flag) {
        url = "/administrativeIssue.do?method=searchAdministrativeIssue&DIV_IDX=" + scwin.DIV_IDX_ADMISU_MST + "&TRS_IDX=" + scwin.TRS_IDX_NEWSEL2 + "&ISUR_CD=" + Isur_cd + "&ISU_CD=" + Isu_cd;
        // 현재 작업이 회사별일 경우

    } else {
        url = "/administrativeIssue.do?method=searchAdministrativeIssue&DIV_IDX=" + scwin.DIV_IDX_ADMISU_MST + "&TRS_IDX=" + scwin.TRS_IDX_NEWSEL + "&ISUR_CD=" + Isur_cd;
    }
    param_Dts.DataID = encodeURI(url);
    param_Dts.reset();

    /*
	관리종목지정업무구분코드
	0:관리종목지정
	1:관리종목사유변경
	2:관리종목사유및유의사항변경
    3:유의사항변경
    4:관리종목지정해제
	5:상장폐지기준적용유예
    6:상장폐지기준적용유예기간변경
	*/

    var type = param_Dts.getCellData(1, "ADMISU_DESIGN_BZ_TP_CD"); //관리종목지정업무구분코드
    var maxDate = param_Dts.getCellData(1, "MKTACT_ENFORCE_DD"); //시행일
    var mktactApplObjTpCd = param_Dts.getCellData(1, "MKTACT_APPL_OBJ_TP_CD"); //시장조치적용대상구분코드(1:종목별, 2:회사별)

    //지정일자 체크
    if (maxDate >= $c.stf.getObjectValue(obj)) {
        alert($c.stf.getMessageParam("MSG-0020", ""));
        return false;
    }

    // 현재 작업이 종목별일 경우
    if (flag) {
        //과거 이력이 종목일 경우 
        if (mktactApplObjTpCd == '1') {
            // 지정일 경우는 직전 이력이 해제여야 함
            if (tpCd == '0') {
                if (type == '4' || type == null) isFlag = true;
            }
            // 해제일경우는 직전이 해제가 아니여야 함
            else if (tpCd == '4' || tpCd == '5') {
                if (type != '4' && type != null) isFlag = true;
            }
            // 상장폐지기준적용유예 기간변경일 경우는 직전이 유예여야 함
            else if (tpCd == '6') {
                if (type == '5') isFlag = true;
            }
            // 기타는 직전이 해제만 아니면됨. 
            else if (tpCd == '1' || tpCd == '2' || tpCd == '3') {
                if (type != '4' && type != null) isFlag = true;
            }
            //과거 이력이 회사일 경우

        } else if (mktactApplObjTpCd == '2') {
            isFlag = false;
        } else {
            isFlag = true;
        }

        // 현재 작업이 회사별일 경우

    } else {
        //과거 이력이 종목별일 경우 
        if (mktactApplObjTpCd == null || mktactApplObjTpCd == '1') {
            isFlag = true;
            //과거 이력이 회사별일 경우

        } else if (mktactApplObjTpCd == '2') {
            // 지정일 경우는 직전이 해제여야 함
            if (tpCd == '0') {
                if (type == '4' || type == null) isFlag = true;
            }
            // 해제일경우는 직전이 해제가 아니여야 함
            else if (tpCd == '4' || tpCd == '5') {
                if (type != '4' && type != null) isFlag = true;
            }
            // 상장폐지기준적용유예 기간변경일 경우는 직전이 유예여야 함
            else if (tpCd == '6') {
                if (type == '5') isFlag = true;
            }
            // 기타는 직전이 해제만 아니면됨. 
            else if (tpCd == '1' || tpCd == '2' || tpCd == '3') {
                if (type != '4' && type != null) isFlag = true;
            }
        }
    }
    if (!isFlag) alert($c.stf.getMessageParam("MSG-0021", ""));
    return isFlag;
};


/*
