/**
 * @method
 * @name fn_getMst_K_Status
 * @description desc
 * @param {string} param_Dts desc
 * @param {string} tpCd desc
 * @param {string} obj desc
 * @param {string} flag desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getMst_K_Status = function(param_Dts, tpCd, obj, flag) {
    var isFlag = false;
    var url = "";

    // 현재 작업이 종목별일 경우
    if (flag) {
        url = "/administrativeIssue.do?method=searchAdministrativeIssue&DIV_IDX=" + scwin.DIV_IDX_ADMISU_MST_K + "&TRS_IDX=" + scwin.TRS_IDX_NEWSEL2 + "&ISUR_CD=" + Isur_cd + "&ISU_CD=" + Isu_cd;
        // 현재 작업이 회사별일 경우

    } else {
        url = "/administrativeIssue.do?method=searchAdministrativeIssue&DIV_IDX=" + scwin.DIV_IDX_ADMISU_MST_K + "&TRS_IDX=" + scwin.TRS_IDX_NEWSEL + "&ISUR_CD=" + Isur_cd;
    }
    param_Dts.DataID = encodeURI(url);
    param_Dts.reset();

    /*
    사유변동구분코드
    0:해제
    1:지정
    2:일부추가
    3:일부해제
    4:일부추가 및 일부해제
    */

    var type = param_Dts.getCellData(1, "RSN_CHG_TP_CD");
    var maxDate = param_Dts.getCellData(1, "ADMISU_DESNRELS_DD");
    var mktactApplObjTpCd = param_Dts.getCellData(1, "MKTACT_APPL_OBJ_TP_CD"); //시장조치적용대상구분코드(1:종목별, 2:회사별)

    /* 2009.04.07 관리종목 하루 동안 다수건 제출이 가능하도록 수정
    alert("maxDate-->"+maxDate);	
    alert("getObjectValue(obj)-->"+getObjectValue(obj));	
    if (maxDate >= getObjectValue(obj)) {
    	alert(getMessageParam("MSG-0020", "")); return false;
    }
    */

    // 현재 작업이 종목별일 경우
    if (flag) {
        //과거 이력이 종목일 경우 
        if (mktactApplObjTpCd == '1') {
            // 지정일 경우는 직전이 해제여야 함
            if (tpCd == '1') {
                if (type == '0' || type == null) isFlag = true;
            }
            // 해제일경우는 직전이 해제가 아니여야 함
            else if (tpCd == '0') {
                if (type != '0' && type != null) isFlag = true;
            }
            // 기타는 직전이 해제만 아니면됨. 
            else if (tpCd == '2' || tpCd == '3' || tpCd == '4') {
                if (type != '0' && type != null) isFlag = true;
            }
            //과거 이력이 회사일 경우

        } else if (mktactApplObjTpCd == '2') {
            isFlag = false;
        } else {
            isFlag = true;
        }

        // 현재 작업이 회사별일 경우

    } else {
        //과거 이력이 종목별일 경우 
        if (mktactApplObjTpCd == null || mktactApplObjTpCd == '1') {
            isFlag = true;
            //과거 이력이 회사별일 경우

        } else if (mktactApplObjTpCd == '2') {
            // 지정일 경우는 직전이 해제여야 함
            if (tpCd == '1') {
                if (type == '0' || type == null) isFlag = true;
            }
            // 해제일경우는 직전이 해제가 아니여야 함
            else if (tpCd == '0') {
                if (type != '0' && type != null) isFlag = true;
            }
            // 기타는 직전이 해제만 아니면됨. 
            else if (tpCd == '2' || tpCd == '3' || tpCd == '4') {
                if (type != '0' && type != null) isFlag = true;
            }
        }
    }
    if (!isFlag) alert($c.stf.getMessageParam("MSG-0021", ""));
    return isFlag;
};


/*
 * 관리종목지정(ETN) 관련해서
 * 현재 업무를 저장할수 있는지 여부를 판단해줌
 */
/**
 * @method
 * @name fn_getMstStatus_etn
 * @description desc
 * @param {string} param_Dts desc
 * @param {string} tpCd desc
 * @param {string} obj desc
 * @param {string} isu_cd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getMstStatus_etn = function(param_Dts, tpCd, obj, isu_cd) {
    var isFlag = false;
    var url = "/etn/EtnMktAct.do?method=searchEtnAdministrativeIssue&DIV_IDX=" + scwin.DIV_ETN_IDX_ADMISU_MST + "&TRS_IDX=" + scwin.TRS_IDX_NEWSEL + "&ISU_CD=" + isu_cd;
    param_Dts.DataID = encodeURI(url);
    param_Dts.reset();

    /*
	관리종목지정업무구분코드
	0:관리종목지정
	1:관리종목사유변경
    4:관리종목지정해제
	*/

    var type = param_Dts.getCellData(1, "ADMISU_DESIGN_BZ_TP_CD"); //관리종목지정업무구분코드
    var maxDate = param_Dts.getCellData(1, "MKTACT_ENFORCE_DD"); //시행일

    //지정일자 체크
    if (maxDate >= $c.stf.getObjectValue(obj)) {
        alert("관리종목으로 지정되었거나, 지정이 예정된 종목이 있습니다.\n\n관리종목지정현황을 확인하세요." + "\n\n종목코드 : " + isu_cd + "\n예정일자 : " + maxDate);
        return false;
    }

    // 지정일 경우는 직전 이력이 해제여야 함
    if (tpCd == '0') {
        if (type == '4' || type == null) isFlag = true;
    }
    // 해제일경우는 직전이 해제가 아니여야 함
    else if (tpCd == '4') {
        if (type != '4' && type != null) isFlag = true;
    }
    // 기타는 직전이 해제만 아니면됨. 
    else if (tpCd == '1') {
        if (type != '4' && type != null) isFlag = true;
    } else {
        isFlag = true;
    }
    if (!isFlag) alert("관리종목으로 지정되었거나, 지정이 예정된 종목이 있습니다.\n\n관리종목지정현황을 확인하세요." + "\n\n종목코드 : " + isu_cd);
    return isFlag;
};


