ADMISU_RSN_CD_D = 'D'; // 지정
ADMISU_RSN_CD_R = 'R'; // 해제

/**
 * @method
 * @name fn_isValidityAdmisuRsnCd
 * @description desc
 * @param {string} tpCd desc
 * @param {string} rsnCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_isValidityAdmisuRsnCd = function(tpCd, rsnCd) {
    if (tpCd == scwin.ADMISU_RSN_CD_D) {
        if (rsnCd.substring(0, 1) != '6') {
            alert("지정 사유가 아닙니다. 확인 하시기 바랍니다.");
            return false;
        }
    } else if (tpCd == scwin.ADMISU_RSN_CD_R) {
        if (rsnCd.substring(0, 1) == '6') {
            alert("해제 사유가 아닙니다. 확인 하시기 바랍니다.");
            return false;
        }
    }
    return true;
};



