/*
 * 상장업무처리 메세지 처리
 */
LastJob = "";
/**
 * @method
 * @name fn_isProcess
 * @description desc
 * @param {string} gubun desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_isProcess = function(gubun) {
    if (gubun == 'I') scwin.LastJob = '저장';

    else if (gubun == 'U') scwin.LastJob = '수정';

    else if (gubun == 'D') scwin.LastJob = '삭제';

    else if (gubun == 'R') scwin.LastJob = '해제';

    else if (gubun == 'DSCL') scwin.LastJob = '안내문작성';
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", scwin.LastJob))) return false;
    return true;
};

