 * @param {string} gChdDD desc
 * @param {string} gbzProcsNo desc
 * @param {string} gListBzTpCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_check_bz_doubleinput_etn = function(dtsObj, gIsuCd, gChdDD, gbzProcsNo, gListBzTpCd) {
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=BZ_PROCS_NO_CHECK_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.etn.select.bzprocsno.doublinputchek.condition" + "&{P}param01=" + gIsuCd + "&{P}param02=" + gChdDD + "&{P}param03=" + gbzProcsNo + "&{P}param04=" + gListBzTpCd;
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
    var vPROCS_DDTM = dtsObj.getCellData(1, "DISCLS_PROCS_DDTM");
    var vPROCS_STAT_CD = dtsObj.getCellData(1, "DISCLS_PROCS_STAT_CD");
    if (vPROCS_DDTM == "") {
        return true;
    } else {
        alert("[" + vPROCS_STAT_CD + "]건으로 " + vPROCS_DDTM + "에  이미 입력되어있습니다.");
        return false;
    }
    var gCnt = dtsObj.getCellData(1, "CNT");
    if (gCnt > 0) {
        alert("상장(변경/조치)일자가 동일한 시장안내정보가 이미 입력되었습니다");
        return false;
    } else {
        return true;
    }
};




