/********************************************** 
 * 함수명   : fn_checkFileNameLength
 * @param filName - 체크할 파일명
 * 설명       : 파일명 길이를 체크한다.
 ***********************************************/
/**
 * @method
 * @name fn_checkFileNameLength
 * @description desc
 * @param {string} filName desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_checkFileNameLength = function(filName) {
    var stringList = new Array();
    var fileName = '';
    var fileLength = 0;
    stringList = filName;
    fileName = stringList.substring(stringList.lastIndexOf('\\') + 1);
    if (scwin.fn_getCheckByte('파일명', fileName, 80)) return true;
};


/********************************************** 
 * 함수명   : fn_getCheckByte
 * @param strItemNm - 체크할 항목명
 * @param strVal - 체크할 값
 * @param limitsize - 제한길이
 * 설명       : 제한길이를 체크한다.
 ***********************************************/
/**
 * @method
 * @name fn_getCheckByte
 * @description desc
 * @param {string} strItemNm desc
 * @param {string} strVal desc
 * @param {string} limitsize desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getCheckByte = function(strItemNm, strVal, limitsize) {
    var len = scwin.fn_getByteLength(strVal);
    if (limitsize < len) {
        alert("입력된 [" + strItemNm + "]은 " + len + "Byte로 \n제한 길이인 " + limitsize + "Byte를 초과 하였습니다. ");
        return false;
    }
    return true;
};


/********************************************** 
 * 함수명   : fn_getByteLength
 * 입력된 S에 해당하는 값의 길이를 Check 해서 Return. 
 * 한글 영숫자 혼합체크가 가능함.
 * 한글1문자는 2Byte  영숫자 1자는 1Byte 임.
 * 설명       : 주어진 항목의 Byte크기를 알아낸다.
 ***********************************************/
/**
 * @method
 * @name fn_getByteLength
 * @description desc
 * @param {string} s desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getByteLength = function(s) {
    var len = 0;
    if (s == null) return 0;
    for (var i = 0; i < s.length; i++) {
        var c = escape(s.charAt(i));
        if (c.length == 1) {
            // ASCII 코드로 구현될수 있는 영숫자인경우 ( 1Byte)
            len++;
        } else if (c.indexOf("%u") != -1) {
            // 한글 및 특수문자인경우 ( DB가 UTF-8 인경우 3Byte 처리 )
            //len += 3;
            len += 2;
        } else if (c.indexOf("%") != -1) {
            // ASCII 코드로 구현될수 있는 영숫자 이외의 문자인경우 ( 1Byte)  
            len += (c.length / 3);
        }
    }
    return len;
};


