/******************************************************************* 
 * 함수명   : fn_SetSrtyCombo
 * 설명     : 콤보데이터를 설정한다.
 * argument : vScrenID, dtsObj, CD_ID_M
 *******************************************************************/
/**
 * @method
 * @name fn_SetSrtyCombo
 * @description desc
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} CD_ID_M desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_SetSrtyCombo = function(vScrenID, dtsObj, CD_ID_M) {
    var url = "/CodeAction.do?method=listCodeValueNameM";
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&SCREN_ID=" + vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&CD_ID_M='" + scwin.fn_getMappingColNm(CD_ID_M) + "'";
    dtsObj.SyncLoad = "true";
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
    dtsObj.InsertRow(dtsObj.getFocusedRowIndex());
    scwin.fn_ResetCdValue(dtsObj);
};


/******************************************************************* 
 * 함수명   : fn_ResetCdValue
 * 설명     : 콤보데이터를 'CODE VALUE' 형태로 재가공한다.
 * argument : cbDs
 *******************************************************************/
/**
 * @method
 * @name fn_ResetCdValue
 * @description desc
 * @param {string} cbDs desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ResetCdValue = function(cbDs) {
    for (var i = 1; i <= cbDs.getTotalRow(); i++) {
        cbDs.setCellData(i, "TEXT", cbDs.getCellData(i, "VALUE") + ' ' + cbDs.getCellData(i, "TEXT"));
    }
};



/******************************************************************* 
 * 함수명   : fn_getMappingColNm
 * 설명     : 메타에서 사용되는 공통코드 id를 column명으로 리턴한다.
 * argument : CD_ID
 *******************************************************************/
/**
 * @method
 * @name fn_getMappingColNm
 * @description desc
 * @param {string} cdId desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getMappingColNm = function(cdId) {
    //국가코드
    if (cdId == "01371") {
        return "CNTR_CD";
    }
    //표준코드기관상태코드
    else if (cdId == "03473") {
        return "STD_CD_INST_STAT_CD";
    }
    return cdId;
};


