/******************************************************************* 
 * 함수명   : fn_SetPopupPos
 * 설명     : 팝업 위치를 설정
 * argument : object
 *******************************************************************/
/**
 * @method
 * @name fn_SetPopupPos
 * @description desc
 * @param {string} grdObj desc
 * @param {string} Tg desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_SetPopupPos = function(grdObj, Tg) {
    var cL = 7;
    var cT = 53;
    if (Tg == "G") {
        cL = 3;
        cT = 22;
    }
    obj_left = grdObj.style.left;
    obj_left = obj_left.substring(0, obj_left.length - 2);
    obj_left = eval(obj_left) + cL;
    obj_top = grdObj.style.top;
    obj_top = obj_top.substring(0, obj_top.length - 2);
    obj_top = eval(obj_top) + cT;
};
